/**
 * Built-in lyrics, keyed by file name (without `.lrc`), which is what `Track.lyricsId`
 * refers to. Every `.lrc` file in this folder is picked up automatically.
 *
 * The five demo files are generated by `npm run generate:lrc` from the compositions;
 * add your own files here by hand (see README → "Use your own music and lyrics").
 */
const files = import.meta.glob<string>('./*.lrc', { query: '?raw', import: 'default', eager: true });

export const BUILTIN_LYRICS: Record<string, string> = Object.fromEntries(
  Object.entries(files).map(([path, text]) => [path.replace(/^\.\//, '').replace(/\.lrc$/, ''), text]),
);
